t.script:
document.addEventListener('DOMContentLoaded', function () {
    var hasArea = truefalse;
    if (!hasArea) {
        var el = document.getElementById('modal-area');
        if (el && window.bootstrap) {
            new bootstrap.Modal(el).show();
        } else if (el) {
            el.classList.add('show');
            el.style.display = 'block';
        }
        return;
    }

    function parseJson(id, fallback) {
        var node = document.getElementById(id);
        if (!node) return fallback;
        try { return JSON.parse(node.textContent); } catch (e) { return fallback; }
    }

    var tree = parseJson('ets-steps-json', {});
    var otroValue = (tree && tree.otro_value) || 'Otras';
    var stack = [];
    var phase = 'browse';
    var selectedCourseName = '';
    var selectedLabel = '';
    var courseFilter = '';
    var openGroups = {};

    var progressEl = document.getElementById('ets-progress');
    var browsePanel = document.getElementById('ets-browse-panel');
    var contactPanel = document.getElementById('ets-contact-panel');
    var bodyEl = document.getElementById('ets-step-body');
    var titleEl = document.getElementById('ets-step-title');
    var subEl = document.getElementById('ets-step-sub');
    var crumbEl = document.getElementById('ets-crumb');
    var backBtn = document.getElementById('ets-back');
    var backContactBtn = document.getElementById('ets-back-contact');
    var noteEl = document.getElementById('ets-note');
    var errorEl = document.getElementById('ets-catalog-error');
    var modalityField = document.getElementById('field_modality');
    var courseField = document.getElementById('field_course');
    var otroWrap = document.getElementById('campo_curso_otro');
    var otroInp = document.getElementById('curso_otro');
    var chipLabel = document.getElementById('ets-selection-label');
    var clearBtn = document.getElementById('ets-clear-selection');
    var submitBtn = document.getElementById('btn-enviar');
    var contactFields = [
        document.getElementById('field_name'),
        document.getElementById('phone'),
        document.getElementById('field_email'),
        document.getElementById('field_colaborador'),
    ];

    var ICONS = {
        graduation: '',
        tools: '',
        code: '',
        university: '',
        laptop: '',
        briefcase: '',
        book: '',
        course: '',
        other: '',
        year: ''
    };

    function iconHtml(key) {
        return '<span class="ets-choice-icon">' + (ICONS[key] || ICONS.course) + '</span>';
    }

    function setContactEnabled(enabled) {
        contactFields.forEach(function (f) {
            if (!f) return;
            if (enabled) f.removeAttribute('disabled');
            else f.setAttribute('disabled', 'disabled');
        });
        if (submitBtn) {
            if (enabled) submitBtn.removeAttribute('disabled');
            else submitBtn.setAttribute('disabled', 'disabled');
        }
    }

    function setOtroVisible(show) {
        if (!otroWrap || !otroInp) return;
        otroWrap.classList.toggle('d-none', !show);
        if (show) {
            otroInp.removeAttribute('disabled');
            otroInp.setAttribute('required', 'required');
        } else {
            otroInp.removeAttribute('required');
            otroInp.setAttribute('disabled', 'disabled');
            otroInp.value = '';
        }
    }

    function clearSelection() {
        selectedCourseName = '';
        selectedLabel = '';
        if (modalityField) modalityField.value = '';
        if (courseField) courseField.value = '';
        setOtroVisible(false);
        setContactEnabled(false);
        if (chipLabel) chipLabel.textContent = '';
    }

    function showPhase(next) {
        phase = next;
        if (browsePanel) browsePanel.classList.toggle('d-none', phase !== 'browse');
        if (contactPanel) contactPanel.classList.toggle('d-none', phase !== 'contact');
        renderProgress();
        if (phase === 'contact') {
            setContactEnabled(true);
            if (selectedCourseName === otroValue && otroInp) otroInp.focus();
            else {
                var name = document.getElementById('field_name');
                if (name) name.focus();
            }
            if (contactPanel) contactPanel.scrollIntoView({ behavior: 'smooth', block: 'start' });
        }
    }

    function currentBrowseStep() {
        if (!stack.length) return 1;
        var frame = stack[stack.length - 1];
        if (frame.type === 'courses') return 3;
        return 2;
    }

    function renderProgress() {
        if (!progressEl) return;
        progressEl.innerHTML = '';
        var labels = ['1 Programa', '2 Opción', '3 Curso', '4 Datos'];
        var active = phase === 'contact' ? 4 : currentBrowseStep();
        labels.forEach(function (label, idx) {
            var n = idx + 1;
            var span = document.createElement('span');
            span.textContent = label;
            if (n === active) span.className = 'is-active';
            else if (n < active) span.className = 'is-done';
            progressEl.appendChild(span);
        });
    }

    function makeChoice(opts) {
        var btn = document.createElement('button');
        btn.type = 'button';
        btn.className = 'ets-choice' + (opts.selected ? ' is-selected' : '');
        btn.innerHTML =
            iconHtml(opts.icon || 'course') +
            '<span class="ets-choice-body">' +
                '<p class="ets-choice-title"></p>' +
                (opts.subtitle ? '<p class="ets-choice-sub"></p>' : '') +
            '</span>' +
            (opts.badge ? '<span class="ets-choice-meta"></span>' : '') +
            '<span class="ets-choice-chevron" aria-hidden="true">›</span>';
        btn.querySelector('.ets-choice-title').textContent = opts.title || '';
        if (opts.subtitle) btn.querySelector('.ets-choice-sub').textContent = opts.subtitle;
        if (opts.badge) btn.querySelector('.ets-choice-meta').textContent = opts.badge;
        if (opts.onClick) btn.addEventListener('click', opts.onClick);
        return btn;
    }

    function makeRow(opts) {
        var btn = document.createElement('button');
        btn.type = 'button';
        btn.className = 'ets-row' + (opts.selected ? ' is-selected' : '');
        btn.innerHTML =
            '<span class="ets-choice-body">' +
                '<p class="ets-row-title"></p>' +
                (opts.subtitle ? '<p class="ets-row-sub"></p>' : '') +
            '</span>' +
            '<span class="ets-row-mark" aria-hidden="true">✓</span>';
        btn.querySelector('.ets-row-title').textContent = opts.title || '';
        if (opts.subtitle) btn.querySelector('.ets-row-sub').textContent = opts.subtitle;
        if (opts.onClick) btn.addEventListener('click', opts.onClick);
        return btn;
    }

    function renderCrumb() {
        if (!crumbEl) return;
        crumbEl.innerHTML = '';
        if (!stack.length) return;
        var home = document.createElement('button');
        home.type = 'button';
        home.textContent = 'Programa';
        home.addEventListener('click', function () {
            stack = [];
            courseFilter = '';
            openGroups = {};
            clearSelection();
            showPhase('browse');
            render();
        });
        crumbEl.appendChild(home);
        stack.forEach(function (frame, idx) {
            var sep = document.createElement('span');
            sep.className = 'sep';
            sep.textContent = '/';
            crumbEl.appendChild(sep);
            var b = document.createElement('button');
            b.type = 'button';
            b.textContent = frame.crumb || frame.title || ('Paso ' + (idx + 1));
            b.addEventListener('click', function () {
                stack = stack.slice(0, idx + 1);
                courseFilter = '';
                clearSelection();
                showPhase('browse');
                render();
            });
            crumbEl.appendChild(b);
        });
    }

    function pushFrame(frame) {
        clearSelection();
        courseFilter = '';
        openGroups = {};
        stack.push(frame);
        showPhase('browse');
        render();
    }

    function applySelection(modality, courseName, modalityLabel) {
        selectedCourseName = courseName || '';
        selectedLabel = (modalityLabel || modality || '') + (courseName ? ' · ' + courseName : '');
        if (modalityField) modalityField.value = modality || '';
        if (courseField) courseField.value = courseName || '';
        var isOtro = courseName === otroValue;
        setOtroVisible(isOtro);
        if (chipLabel) chipLabel.textContent = selectedLabel;
        showPhase('contact');
    }

    function renderCourses(frame) {
        var courses = frame.courses || [];
        var modality = frame.modality_value || '';
        var modalityLabel = frame.modality_label || frame.title || '';
        var q = (courseFilter || '').toLowerCase().trim();

        var tools = document.createElement('div');
        tools.className = 'ets-tools';
        var input = document.createElement('input');
        input.type = 'search';
        input.placeholder = 'Buscar curso...';
        input.value = courseFilter;
        input.addEventListener('input', function () {
            courseFilter = this.value || '';
            render();
            var again = document.querySelector('#ets-step-body input[type=search]');
            if (again) {
                again.focus();
                var val = again.value;
                again.setSelectionRange(val.length, val.length);
            }
        });
        tools.appendChild(input);
        bodyEl.appendChild(tools);

        var groups = {};
        var order = [];
        courses.forEach(function (c) {
            if (q && String(c.nombre || '').toLowerCase().indexOf(q) === -1) return;
            var g = c.area_nombre || 'Cursos disponibles';
            if (!groups[g]) {
                groups[g] = [];
                order.push(g);
            }
            groups[g].push(c);
        });

        var scroll = document.createElement('div');
        scroll.className = 'ets-course-scroll';

        if (!order.length) {
            var empty = document.createElement('div');
            empty.className = 'ets-empty';
            empty.style.border = '0';
            empty.textContent = q
                ? 'No hay cursos que coincidan con la búsqueda.'
                : 'No hay cursos disponibles en esta opción por ahora.';
            scroll.appendChild(empty);
        } else {
            order.forEach(function (gName, gIdx) {
                var group = document.createElement('div');
                group.className = 'ets-group';
                var open = openGroups[gName];
                if (typeof open === 'undefined') open = order.length === 1 || gIdx === 0 || !!q;
                openGroups[gName] = open;

                var toggle = document.createElement('button');
                toggle.type = 'button';
                toggle.className = 'ets-group-toggle';
                toggle.innerHTML = '<span></span><span class="count"></span>';
                toggle.querySelector('span').textContent = (open ? '▾ ' : '▸ ') + gName;
                toggle.querySelector('.count').textContent = groups[gName].length;
                toggle.addEventListener('click', function () {
                    openGroups[gName] = !openGroups[gName];
                    render();
                });
                group.appendChild(toggle);

                if (open) {
                    groups[gName].forEach(function (c) {
                        group.appendChild(makeRow({
                            title: c.nombre,
                            subtitle: c.anio_curso ? ('Año ' + c.anio_curso) : '',
                            selected: selectedCourseName === c.nombre,
                            onClick: function () {
                                applySelection(modality, c.nombre, modalityLabel);
                            }
                        }));
                    });
                }
                scroll.appendChild(group);
            });
        }
        bodyEl.appendChild(scroll);

        var footer = document.createElement('div');
        footer.className = 'ets-footer-row';
        footer.appendChild(makeChoice({
            title: 'Otro',
            subtitle: 'Si no aparece tu curso, especifícalo',
            icon: 'other',
            selected: selectedCourseName === otroValue,
            onClick: function () {
                applySelection(modality, otroValue, modalityLabel);
            }
        }));
        bodyEl.appendChild(footer);
    }

    function renderRoot() {
        var list = document.createElement('div');
        list.className = 'ets-choice-list';
        (tree.options || []).forEach(function (opt) {
            list.appendChild(makeChoice({
                title: (opt.num ? opt.num + '. ' : '') + (opt.title || ''),
                subtitle: opt.subtitle || '',
                badge: opt.badge || '',
                icon: opt.icon || 'graduation',
                onClick: function () {
                    if (opt.suboptions && opt.suboptions.length) {
                        pushFrame({
                            type: 'suboptions',
                            title: opt.title,
                            subtitle: opt.subtitle,
                            crumb: opt.title,
                            items: opt.suboptions,
                        });
                    } else {
                        pushFrame({
                            type: 'courses',
                            title: opt.title,
                            subtitle: 'Elige un curso para continuar',
                            crumb: opt.title,
                            modality_value: opt.modality_value,
                            modality_label: opt.modality_label || opt.title,
                            note: opt.note || '',
                            courses: opt.courses || [],
                        });
                    }
                }
            }));
        });
        bodyEl.appendChild(list);
    }

    function renderSuboptions(frame) {
        var list = document.createElement('div');
        list.className = 'ets-choice-list';
        (frame.items || []).forEach(function (item) {
            list.appendChild(makeChoice({
                title: item.title || '',
                subtitle: item.subtitle || '',
                badge: item.badge || '',
                icon: item.icon || 'book',
                onClick: function () {
                    if (item.years && item.years.length) {
                        pushFrame({
                            type: 'years',
                            title: item.title,
                            subtitle: 'Selecciona el año académico',
                            crumb: item.title,
                            years: item.years,
                        });
                    } else {
                        pushFrame({
                            type: 'courses',
                            title: item.title,
                            subtitle: 'Elige un curso para continuar',
                            crumb: item.title,
                            modality_value: item.modality_value,
                            modality_label: item.modality_label || item.title,
                            note: item.note || '',
                            courses: item.courses || [],
                        });
                    }
                }
            }));
        });
        bodyEl.appendChild(list);
    }

    function renderYears(frame) {
        var list = document.createElement('div');
        list.className = 'ets-choice-list';
        (frame.years || []).forEach(function (yr) {
            var count = (yr.courses || []).length;
            list.appendChild(makeChoice({
                title: yr.title || ('Año ' + yr.anio),
                subtitle: yr.subtitle || '',
                badge: count ? (count + ' cursos') : 'Sin cursos',
                icon: 'year',
                onClick: function () {
                    pushFrame({
                        type: 'courses',
                        title: yr.title,
                        subtitle: 'Elige un curso para continuar',
                        crumb: yr.title,
                        modality_value: yr.modality_value,
                        modality_label: yr.modality_label || yr.title,
                        note: yr.note || '',
                        courses: yr.courses || [],
                    });
                }
            }));
        });
        bodyEl.appendChild(list);
    }

    function render() {
        if (!bodyEl) return;
        bodyEl.innerHTML = '';

        if (!tree || !tree.catalogo_listo || !(tree.options || []).length) {
            if (titleEl) titleEl.textContent = 'Catálogo no disponible';
            if (subEl) subEl.textContent = 'No se pudieron obtener los programas en este momento.';
            if (errorEl) errorEl.classList.remove('d-none');
            if (backBtn) backBtn.classList.add('d-none');
            showPhase('browse');
            setContactEnabled(false);
            return;
        }
        if (errorEl) errorEl.classList.add('d-none');

        var frame = stack.length ? stack[stack.length - 1] : null;
        var stepNo = currentBrowseStep();
        if (titleEl) {
            titleEl.textContent = frame
                ? ('Paso ' + stepNo + ' · ' + (frame.title || 'Selecciona'))
                : 'Paso 1 · Elige tu programa';
        }
        if (subEl) {
            subEl.textContent = frame
                ? (frame.subtitle || 'Continúa con la opción que mejor te represente.')
                : 'Selecciona una de las 3 opciones para continuar.';
        }
        if (noteEl) {
            var note = frame && frame.note ? frame.note : '';
            noteEl.textContent = note;
            noteEl.classList.toggle('d-none', !note);
        }
        if (backBtn) backBtn.classList.toggle('d-none', !stack.length);
        renderCrumb();
        renderProgress();

        if (!frame) renderRoot();
        else if (frame.type === 'suboptions') renderSuboptions(frame);
        else if (frame.type === 'years') renderYears(frame);
        else renderCourses(frame);
    }

    if (backBtn) {
        backBtn.addEventListener('click', function () {
            stack.pop();
            courseFilter = '';
            clearSelection();
            showPhase('browse');
            render();
        });
    }
    if (backContactBtn) {
        backContactBtn.addEventListener('click', function () {
            clearSelection();
            showPhase('browse');
            render();
        });
    }
    if (clearBtn) {
        clearBtn.addEventListener('click', function () {
            clearSelection();
            stack = [];
            courseFilter = '';
            openGroups = {};
            showPhase('browse');
            render();
        });
    }

    var phone = document.getElementById('phone');
    if (phone) {
        phone.addEventListener('input', function () {
            this.value = this.value.replace(/[^0-9]/g, '').slice(0, 8);
        });
    }

    var carnetWrap = document.getElementById('campo_carnet');
    var carnetInp = document.getElementById('carne_principal');
    function toggleCarnet() {
        var sel = document.querySelector('input[name=vinculo_centro]:checked');
        var show = sel && (sel.value === 'egresado' || sel.value === 'estudiante');
        if (carnetWrap) carnetWrap.classList.toggle('d-none', !show);
        if (carnetInp) {
            if (show) carnetInp.setAttribute('required', 'required');
            else {
                carnetInp.removeAttribute('required');
                carnetInp.value = '';
            }
        }
    }
    document.querySelectorAll('input[name=vinculo_centro]').forEach(function (r) {
        r.addEventListener('change', toggleCarnet);
    });
    if (carnetInp) {
        carnetInp.addEventListener('input', function () {
            this.value = this.value.replace(/[^a-zA-Z0-9]/g, '');
        });
    }
    toggleCarnet();

    var form = document.getElementById('form-principal');
    if (form) {
        form.addEventListener('submit', function (ev) {
            if (phase !== 'contact') {
                ev.preventDefault();
                alert('Completa la selección del programa primero.');
                return;
            }
            if (!modalityField || !modalityField.value) {
                ev.preventDefault();
                alert('Selecciona un programa antes de enviar.');
                return;
            }
            if (!courseField || !courseField.value) {
                ev.preventDefault();
                alert('Selecciona un curso antes de enviar.');
                return;
            }
            if (courseField.value === otroValue && (!otroInp || !otroInp.value.trim())) {
                ev.preventDefault();
                alert('Especifica el curso en el campo Otro.');
                return;
            }
            var phoneVal = (phone && phone.value) || '';
            if (phoneVal.length !== 8) {
                ev.preventDefault();
                alert('El teléfono debe tener 8 dígitos.');
            }
        });
    }

    clearSelection();
    showPhase('browse');
    render();
});
